/bin/bash -lc "python3 - <<'PY'
import json
from pathlib import Path
for rel in ['run6/agent/wf/agents/0003-harness-repair/codex-1.jsonl','run6/agent/wf/agents/0004-harness-repair/codex-1.jsonl']:
    print(rel)
    for number, line in enumerate(Path(rel).read_text().splitlines(), 1):
        if not any(term in line.lower() for term in ['apt-cache', '/etc/apt/sources', 'openmpi', 'mpirun']):
            continue
        row=json.loads(line)
        text=json.dumps(row, ensure_ascii=False)
        for term in ['apt-cache', '/etc/apt/sources', 'openmpi', 'mpirun']:
            start=text.lower().find(term)
            if start >= 0:
                print(f'{number}: ...{text[max(0,start-120):start+300]}...')
                break
PY"

